import org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler;

public class Foo {
    private ThreadPoolTaskScheduler bad() {
        ThreadPoolTaskScheduler scheduler = new ThreadPoolTaskScheduler(); //bad
        return scheduler;
    }

    private final ThreadPoolTaskScheduler field = new ThreadPoolTaskScheduler(); //bad
}

import org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler;

public class Foo {
    private ThreadPoolTaskScheduler good() {
        ThreadPoolTaskScheduler scheduler = new ThreadPoolTaskScheduler();
        scheduler.setPoolSize(5);
        return scheduler;
    }
}

import org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler;

public class Foo {
    ThreadPoolTaskScheduler viaHelper() {
        ThreadPoolTaskScheduler scheduler = new ThreadPoolTaskScheduler();
        configure(scheduler);
        return scheduler;
    }

    private void configure(ThreadPoolTaskScheduler scheduler) {
        scheduler.setPoolSize(5);
    }
}

import org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler;

public class Foo {
    ThreadPoolTaskScheduler unrelatedHelper() {
        ThreadPoolTaskScheduler scheduler = new ThreadPoolTaskScheduler(); //bad
        decorate(scheduler);
        return scheduler;
    }

    private void decorate(ThreadPoolTaskScheduler scheduler) {
        scheduler.setThreadNamePrefix("x-");
    }
}

import org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler;

public class Foo {
    Object two() {
        ThreadPoolTaskScheduler unconfigured = new ThreadPoolTaskScheduler(); //bad
        ThreadPoolTaskScheduler configured = new ThreadPoolTaskScheduler();
        configured.setPoolSize(5);
        return unconfigured;
    }
}

import org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler;

public class Foo {
    private final ThreadPoolTaskScheduler scheduler = new ThreadPoolTaskScheduler(); //bad

    void other() {
        ThreadPoolTaskScheduler scheduler = new ThreadPoolTaskScheduler();
        scheduler.setPoolSize(5);
    }
}
